WITH valid AS (SELECT *, GREATEST(discount, amount) AS greatest_discount_amount, CONCAT_WS('-', channel, status) AS channel_status_key FROM orders WHERE store_id IN (4, 22, 34)) SELECT id, customer_id, store_id, order_date, status, channel, amount, discount, shipping_fee, greatest_discount_amount, channel_status_key, DENSE_RANK() OVER (PARTITION BY channel ORDER BY greatest_discount_amount NULLS FIRST) AS greatest_discount_amount_dense_rank, SUM(discount) OVER (PARTITION BY customer_id ORDER BY discount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_discount, LAG(shipping_fee, 2) OVER (PARTITION BY store_id, customer_id ORDER BY order_date, id) AS prev_shipping_fee, MAX(shipping_fee) OVER w_recent AS status_max_shipping_fee, ROUND(amount / SUM(amount) OVER (PARTITION BY store_id), 4) AS amount_share FROM valid WINDOW w_recent AS (PARTITION BY status)
